```
dp[i][j] = min delete cost for s1[i:] and s2[j:]
base: dp[n][j] = sum of s2[j:], dp[i][m] = sum of s1[i:]
for i = n-1 down to 0:
  for j = m-1 down to 0:
    if s1[i] == s2[j]:
      dp[i][j] = dp[i+1][j+1]
    else:
      dp[i][j] = min(s1[i] + dp[i+1][j], s2[j] + dp[i][j+1])
return dp[0][0]
```

code.cpp:
class Solution {
public:
    int minimumDeleteSum(string s1, string s2) {
        int n = s1.size(), m = s2.size();
        if (n < m) {
            swap(s1, s2);
            swap(n, m);
        }

        vector<int> dp(m + 1, 0);

        for (int j = m - 1; j >= 0; j--) {
            dp[j] = dp[j + 1] + s2[j];
        }

        for (int i = n - 1; i >= 0; i--) {
            int diag = dp[m];
            dp[m] += s1[i];
            for (int j = m - 1; j >= 0; j--) {
                int temp = dp[j];
                if (s1[i] == s2[j]) {
                    dp[j] = diag;
                } else {
                    dp[j] = min(s1[i] + temp, s2[j] + dp[j + 1]);
                }
                diag = temp;
            }
        }

        return dp[0];
    }
};
